CREATE TRIGGER growth_feedback_insert INSTEAD OF INSERT ON growth_feedback BEGIN
 SELECT CASE WHEN NEW.submission_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM lesson_submissions WHERE tenant_id=NEW.tenant_id AND id=NEW.submission_id AND lesson_id=NEW.lesson_id) THEN RAISE(ABORT,'invalid_feedback_submission') END;
 SELECT CASE WHEN NEW.submission_id IS NULL AND NOT EXISTS(SELECT 1 FROM lesson_comments WHERE tenant_id=NEW.tenant_id AND lesson_id=NEW.lesson_id AND student_id=NEW.student_id) THEN RAISE(ABORT,'invalid_feedback_comment') END;
 UPDATE lesson_submissions SET personal_json=json_insert(personal_json,'$[#]',json_object('id',NEW.id,'lesson_id',NEW.lesson_id,'submission_id',NEW.submission_id,'student_id',NEW.student_id,'seq',NEW.seq,'doc_json',NEW.doc_json,'status',NEW.status,'confirmed_at',NEW.confirmed_at,'created_at',NEW.created_at,'created_by',NEW.created_by,'updated_at',NEW.updated_at,'updated_by',NEW.updated_by,'version',NEW.version,'deleted_at',NEW.deleted_at)) WHERE tenant_id=NEW.tenant_id AND id=NEW.submission_id;
 UPDATE lesson_comments SET feedback_versions_json=json_insert(feedback_versions_json,'$[#]',json_object('id',NEW.id,'lesson_id',NEW.lesson_id,'submission_id',NEW.submission_id,'student_id',NEW.student_id,'seq',NEW.seq,'doc_json',NEW.doc_json,'status',NEW.status,'confirmed_at',NEW.confirmed_at,'created_at',NEW.created_at,'created_by',NEW.created_by,'updated_at',NEW.updated_at,'updated_by',NEW.updated_by,'version',NEW.version,'deleted_at',NEW.deleted_at)) WHERE tenant_id=NEW.tenant_id AND lesson_id=NEW.lesson_id AND student_id=NEW.student_id AND NEW.submission_id IS NULL;
END;
